import React, { useState, useEffect } from 'react';
import { FaTimes, FaSearchPlus, FaChevronLeft, FaChevronRight } from 'react-icons/fa';
import { Link } from 'gatsby';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Pagination, Autoplay } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/pagination';
import './gallery.css';
import { GALLERY } from '../../content';

// Normalise CMS images to the same shape as galleryImages
function loadCMSImages() {
  if (typeof window === 'undefined') return null;
  const stored = localStorage.getItem('cms_gallery_images');
  if (!stored) return null;
  try {
    const parsed: { id: string; src: string; title: string }[] = JSON.parse(stored);
    if (!parsed.length) return null;
    return parsed.map((img) => ({ id: Number(img.id) || 0, src: img.src, title: img.title }));
  } catch {
    return null;
  }
}

const Gallery: React.FC = () => {
  const [galleryImages, setGalleryImages] = useState<typeof GALLERY.images>(GALLERY.images);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  // On mount, swap to CMS images if any have been uploaded
  useEffect(() => {
    const cms = loadCMSImages();
    if (cms) setGalleryImages(cms);
  }, []);

  const openLightbox = (index: number) => {
    setCurrentImageIndex(index);
    setLightboxOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeLightbox = () => {
    setLightboxOpen(false);
    document.body.style.overflow = 'unset';
  };

  const nextImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev + 1) % galleryImages.length);
  };

  const prevImage = (e: React.MouseEvent) => {
    e.stopPropagation();
    setCurrentImageIndex((prev) => (prev - 1 + galleryImages.length) % galleryImages.length);
  };

  return (
    <section className="gallery-section" id="gallery">
      <div className="container">
        <div className="gallery-header">
          <div className="section-tag">
            <span>{GALLERY.sectionTag}</span>
          </div>
          <h2 className="gallery-title">
            {GALLERY.title} <span className="highlight">{GALLERY.titleHighlight}</span>
          </h2>
          <p className="gallery-subtitle">
            {GALLERY.subtitle}
          </p>
        </div>

        {/* Desktop Showcase Grid */}
        <div className="desktop-only">
          {/* Row 1: 1 big + 4 thumbs */}
          <div className="showcase-row1">
            <div className="showcase-featured" onClick={() => openLightbox(0)}>
              <img src={galleryImages[0].src} alt={galleryImages[0].title} className="showcase-img" loading="lazy" />
              <div className="showcase-overlay">
                <FaSearchPlus className="showcase-zoom" />
                <span className="showcase-title">{galleryImages[0].title}</span>
              </div>
            </div>
            <div className="showcase-thumbs">
              {galleryImages.slice(1, 5).map((image, i) => (
                <div key={image.id} className="showcase-thumb" onClick={() => openLightbox(i + 1)}>
                  <img src={image.src} alt={image.title} className="showcase-img" loading="lazy" />
                  <div className="showcase-overlay">
                    <FaSearchPlus className="showcase-zoom" />
                    <span className="showcase-title">{image.title}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
          {/* Row 2: equal-width strip */}
          <div className="showcase-row2">
            {galleryImages.slice(5, 12).map((image, i) => (
              <div key={image.id} className="showcase-strip" onClick={() => openLightbox(i + 5)}>
                <img src={image.src} alt={image.title} className="showcase-img" loading="lazy" />
                <div className="showcase-overlay">
                  <FaSearchPlus className="showcase-zoom" />
                  <span className="showcase-title">{image.title}</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Mobile Swiper */}
        <div className="mobile-only gallery-swiper-container">
          <Swiper
            modules={[Pagination, Autoplay]}
            spaceBetween={20}
            slidesPerView={1.2}
            centeredSlides={true}
            loop={true}
            autoplay={{ delay: 3500, disableOnInteraction: false }}
            pagination={{ clickable: true }}
            className="gallery-swiper"
          >
            {galleryImages.map((image, index) => (
              <SwiperSlide key={image.id} onClick={() => openLightbox(index)}>
                <div className="gallery-card mobile-card">
                  <div className="gallery-img-wrapper">
                    <img src={image.src} alt={image.title} className="gallery-img" loading="lazy" />
                    <div className="mobile-overlay-info">
                      <h3>{image.title}</h3>
                    </div>
                  </div>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>
        </div>

        
      </div>

      {/* Lightbox Overlay */}
      {lightboxOpen && (
        <div className="lightbox-overlay" onClick={closeLightbox}>
          <div className="lightbox-close" onClick={closeLightbox}>
            <FaTimes />
          </div>

          <div className="lightbox-nav-btn prev" onClick={prevImage}>
            <FaChevronLeft />
          </div>
          
          <div className="lightbox-content" onClick={(e) => e.stopPropagation()}>
            <img 
              src={galleryImages[currentImageIndex].src} 
              alt={galleryImages[currentImageIndex].title} 
              className="lightbox-main-img"
            />
            <div className="lightbox-caption">
              <h4>{galleryImages[currentImageIndex].title}</h4>
            </div>
          </div>

          <div className="lightbox-nav-btn next" onClick={nextImage}>
            <FaChevronRight />
          </div>
        </div>
      )}
    </section>
  );
};

export default Gallery;

