import React from 'react';
import './services.css';
import {
  FaArrowRight, FaHardHat, FaTools, FaIndustry,
  FaTree, FaLayerGroup, FaShieldAlt, FaLeaf, FaAward, FaStar,
  FaPaintRoller,
} from 'react-icons/fa';
import { SERVICES, SERVICES_SECTION, ServiceData } from '../../content';

const getServiceIcon = (iconName: string) => {
  switch (iconName) {
    case 'FaHardHat':    return <FaHardHat />;
    case 'FaTools':      return <FaTools />;
    case 'FaIndustry':   return <FaIndustry />;
    case 'FaTree':       return <FaTree />;
    case 'FaLayerGroup': return <FaLayerGroup />;
    case 'FaShieldAlt':  return <FaShieldAlt />;
    case 'FaLeaf':       return <FaLeaf />;
    case 'FaAward':      return <FaAward />;
    case 'FaStar':       return <FaStar />;
    case 'FaPaintRoller':return <FaPaintRoller />;
    default:             return <FaHardHat />;
  }
};

const Services: React.FC = () => {
  return (
    <section className="services" id="services">
      <div className="services-container">

        {/* ── Section Header ── */}
        <div className="services-header">
          <span className="services-badge">{SERVICES_SECTION.badge}</span>
          <h2 className="services-title">{SERVICES_SECTION.title}</h2>
          <p className="services-subtitle">{SERVICES_SECTION.subtitle}</p>
        </div>

        {/* ── 3 × 3 Grid ── */}
        <div className="services-grid">
          {SERVICES.map((service: ServiceData, idx: number) => (
            <a
              key={service.id}
              href={`/${service.slug}`}
              className="service-card"
            >
              {/* Image */}
              <div className="sc-image">
                <img src={service.image} alt={service.imageAlt} />
                {/* Number badge */}
                <span className="sc-number">
                  {String(idx + 1).padStart(2, '0')}
                </span>
                {/* Icon badge */}
                <span className="sc-icon">
                  {getServiceIcon(service.icon)}
                </span>
              </div>

              {/* Content */}
              <div className="sc-body">
                <div className="sc-accent" />
                <h3 className="sc-title">{service.title}</h3>
                <p className="sc-desc">{service.description}</p>
                <span className="sc-link">
                  Learn More <FaArrowRight className="sc-arrow" />
                </span>
              </div>
            </a>
          ))}
        </div>

      </div>
    </section>
  );
};

export default Services;
