import React from 'react';
import './about.css';
import { FaCheckCircle, FaStar, FaAward, FaTools, FaMapMarkerAlt, FaClock, FaDollarSign } from 'react-icons/fa';
import { ABOUT, BUSINESS } from '../../content';
import about from '../../images/about.jpg';
const About: React.FC = () => {
  const getHighlightIcon = (iconName: string) => {
    switch (iconName) {
      case 'tools': return <FaTools />;
      case 'map': return <FaMapMarkerAlt />;
      case 'clock': return <FaClock />;
      case 'dollar': return <FaDollarSign />;
      default: return <FaCheckCircle />;
    }
  };

  const getStatIcon = (iconName: string) => {
    switch (iconName) {
      case 'star': return <FaStar className="stat-icon star" />;
      case 'check': return <FaCheckCircle className="stat-icon" />;
      default: return <FaAward className="stat-icon" />;
    }
  };

  return (
    <section className="about" id="about">
      <div className="about-container">
        <div className="about-grid">
          {/* Left content */}
          <div className="about-content">
            <div className="section-tag">
              <FaAward className="tag-icon" />
              <span>{ABOUT.sectionTag}</span>
            </div>
            
            <h2 className="about-title">
              {ABOUT.title} <br /> {ABOUT.titleLine2}
            </h2>
            
            <p className="about-description">
              {ABOUT.description}
            </p>

            <div className="about-stats">
              {ABOUT.stats.map((stat, idx) => (
                <div key={idx} className="stat-item">
                  {getStatIcon(stat.icon)}
                  <div className="stat-info">
                    <strong>{stat.label}</strong>
                    <span>{stat.sublabel}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="about-highlights">
              {ABOUT.highlights.map((highlight, idx) => (
                <div key={idx} className="highlight-item">
                  <span className="highlight-icon">{getHighlightIcon(highlight.icon)}</span>
                  <span>{highlight.text}</span>
                </div>
              ))}
            </div>

            <a href={ABOUT.ctaHref} className="about-cta">
              {ABOUT.ctaText}
            </a>
          </div>

          {/* Right side - Image with creative elements */}
          <div className="about-image">
            <div className="image-wrapper">
              <img 
                src={about}
                alt={ABOUT.imageAlt} 
                className="about-img" 
              />
              <div className="image-overlay">
                <div className="overlay-content">
                  <FaCheckCircle className="overlay-icon" />
                  <span>{ABOUT.overlayText}</span>
                </div>
              </div>
            </div>
            
            {/* Accreditations badge */}
            <div className="image-badge">
              <div className="badge-text">{ABOUT.badgeText}</div>
              <div className="badge-rating">{ABOUT.badgeRating}</div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;